"""Shared Unreal Tools MCP runtime. Plugin copies are generated by sync_runtime.py."""
__version__ = "2.0.0"


def require_runtime(minimum):
    """An imported package cannot be safely replaced in a running Python process."""
    actual, required = tuple(map(int, __version__.split("."))), tuple(map(int, minimum.split(".")))
    if actual < required or actual[0] != required[0]:
        raise RuntimeError(f"Unreal Tools runtime {minimum} or newer is required; loaded {__version__}. "
                           "Start a new Python process using the updated plugin.")
